CREATE FUNCTION "stokit_on_update_advance_pay_allocations"() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
    IF (to_jsonb(NEW) - ARRAY['updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at']) THEN
        IF NEW."updated_at" IS NOT DISTINCT FROM OLD."updated_at" THEN NEW."updated_at" := CURRENT_TIMESTAMP; END IF;
    END IF;
    RETURN NEW;
END
$fn$;
CREATE TRIGGER "trg_advance_pay_allocations_on_update" BEFORE UPDATE ON "advance_pay_allocations" FOR EACH ROW EXECUTE FUNCTION "stokit_on_update_advance_pay_allocations"();

CREATE FUNCTION "stokit_on_update_advance_pay_offers"() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
    IF (to_jsonb(NEW) - ARRAY['updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at']) THEN
        IF NEW."updated_at" IS NOT DISTINCT FROM OLD."updated_at" THEN NEW."updated_at" := CURRENT_TIMESTAMP; END IF;
    END IF;
    RETURN NEW;
END
$fn$;
CREATE TRIGGER "trg_advance_pay_offers_on_update" BEFORE UPDATE ON "advance_pay_offers" FOR EACH ROW EXECUTE FUNCTION "stokit_on_update_advance_pay_offers"();

